#include "dlaa/algorithms.hpp"
#include <algorithm>
#include <limits>
#include <queue>
#include <stdexcept>
#include <tuple>
namespace dlaa::algo {
std::vector<int>dijkstra(int n,const std::vector<Edge>&e,int s){const int I=std::numeric_limits<int>::max()/4;if(s<0||s>=n)throw std::invalid_argument("source");std::vector<std::vector<std::pair<int,int>>>g(n);for(auto x:e){if(x.w<0)throw std::invalid_argument("negative edge in Dijkstra");g[x.u].push_back({x.v,x.w});}std::vector<int>d(n,I);d[s]=0;using P=std::pair<int,int>;std::priority_queue<P,std::vector<P>,std::greater<P>>q;q.push({0,s});while(!q.empty()){auto [du,u]=q.top();q.pop();if(du!=d[u])continue;for(auto [v,w]:g[u])if(d[v]>du+w){d[v]=du+w;q.push({d[v],v});}}return d;}
std::vector<int>bellmanFord(int n,const std::vector<Edge>&e,int s){const int I=std::numeric_limits<int>::max()/4;if(s<0||s>=n)throw std::invalid_argument("source");std::vector<int>d(n,I);d[s]=0;for(int i=1;i<n;++i){bool changed=false;for(auto x:e)if(d[x.u]!=I&&d[x.v]>d[x.u]+x.w){d[x.v]=d[x.u]+x.w;changed=true;}if(!changed)break;}for(auto x:e)if(d[x.u]!=I&&d[x.v]>d[x.u]+x.w)throw std::runtime_error("reachable negative cycle");return d;}
std::vector<std::vector<int>>floydWarshall(std::vector<std::vector<int>>d){int n=(int)d.size(),I=std::numeric_limits<int>::max()/4;for(auto&r:d)if((int)r.size()!=n)throw std::invalid_argument("matrix must be square");for(int k=0;k<n;++k)for(int i=0;i<n;++i)for(int j=0;j<n;++j)if(d[i][k]<I&&d[k][j]<I&&d[i][j]>d[i][k]+d[k][j])d[i][j]=d[i][k]+d[k][j];return d;}
MSTResult kruskal(int n,std::vector<Edge>e){std::sort(e.begin(),e.end(),[](auto a,auto b){return a.w<b.w;});std::vector<int>p(n),r(n);for(int i=0;i<n;++i)p[i]=i;auto root=[&](int x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;};MSTResult o;for(auto x:e){int a=root(x.u),b=root(x.v);if(a!=b){if(r[a]<r[b])std::swap(a,b);p[b]=a;if(r[a]==r[b])++r[a];o.cost+=x.w;o.edges.push_back(x);}}if(n&&o.edges.size()!=(std::size_t)n-1)throw std::runtime_error("disconnected graph");return o;}
MSTResult prim(int n,const std::vector<Edge>&e){std::vector<std::vector<std::pair<int,int>>>g(n);for(auto x:e){g[x.u].push_back({x.v,x.w});g[x.v].push_back({x.u,x.w});}MSTResult o;if(!n)return o;std::vector<char>seen(n);using P=std::tuple<int,int,int>;std::priority_queue<P,std::vector<P>,std::greater<P>>q;q.push({0,0,-1});while(!q.empty()){auto [w,u,par]=q.top();q.pop();if(seen[u])continue;seen[u]=1;if(par!=-1){o.cost+=w;o.edges.push_back({par,u,w});}for(auto [v,c]:g[u])if(!seen[v])q.push({c,v,u});}if(o.edges.size()!=(std::size_t)n-1)throw std::runtime_error("disconnected graph");return o;}
int fordFulkerson(int n,const std::vector<std::vector<int>>&c,int s,int t){if((int)c.size()!=n||s<0||t<0||s>=n||t>=n||s==t)throw std::invalid_argument("flow args");auto r=c;for(auto&v:r)if((int)v.size()!=n)throw std::invalid_argument("capacity matrix");int f=0;while(true){std::vector<int>p(n,-1);std::queue<int>q;q.push(s);p[s]=s;while(!q.empty()&&p[t]<0){int u=q.front();q.pop();for(int v=0;v<n;++v)if(p[v]<0&&r[u][v]>0){p[v]=u;q.push(v);}}if(p[t]<0)break;int a=std::numeric_limits<int>::max();for(int v=t;v!=s;v=p[v])a=std::min(a,r[p[v]][v]);for(int v=t;v!=s;v=p[v]){r[p[v]][v]-=a;r[v][p[v]]+=a;}f+=a;}return f;}
static bool aug(int u,const std::vector<std::vector<int>>&a,std::vector<int>&m,std::vector<char>&s){for(int v:a[u])if(v>=0&&v<(int)m.size()&&!s[v]){s[v]=1;if(m[v]<0||aug(m[v],a,m,s)){m[v]=u;return true;}}return false;}
int maximumBipartiteMatching(const std::vector<std::vector<int>>&a,int nr){std::vector<int>m(nr,-1);int count=0;for(int u=0;u<(int)a.size();++u){std::vector<char>s(nr);if(aug(u,a,m,s))++count;}return count;}
}